// ignore_for_file: deprecated_member_use
import 'dart:html' as html;

/// Court bip (deux notes, ~350ms) généré en WAV et embarqué en base64 —
/// évite de dépendre d'un asset externe ou d'un package audio pour un
/// simple son d'alerte web.
const String _kBeepBase64 =
    '';

/// Chemin du son personnalisé, servi tel quel depuis web/ (comme
/// firebase-messaging-sw.js ou manifest.json) — déposer le fichier à
/// web/sounds/notification_admin.mp3 pour l'utiliser. Fallback sur le bip
/// généré ci-dessus tant qu'aucun fichier n'est présent (404 → catch).
const String _kCustomSoundPath = 'sounds/notification_admin.mp3';

/// Joue le son d'alerte (best-effort, silencieux en cas d'échec —
/// certains navigateurs bloquent l'audio avant une interaction utilisateur).
void playNotificationSound() {
  try {
    final audio = html.AudioElement(_kCustomSoundPath)..volume = 0.8;
    audio.onError.listen((_) {
      // Fichier personnalisé absent/invalide → repli sur le bip embarqué.
      try {
        html.AudioElement('data:audio/wav;base64,$_kBeepBase64')
          ..volume = 0.7
          ..play();
      } catch (_) {}
    });
    audio.play();
  } catch (_) {
    // Ignoré : le son est un bonus, pas critique.
  }
}
